test("parses a signature header with two v1 entries", () => {
  const h = parseSignatureHeader(`t=1731920000,v1=${"a".repeat(64)},v1=${"b".repeat(64)}`);
  assert.equal(h.timestamp, 1731920000);
  assert.equal(h.signatures.length, 2);
