test("signature verification covers rotation, exact bytes, and both timestamp boundaries", () => {
  const body = Buffer.from('{ "event_id": "evt_raw", "label": "₹" }\n');
  const now = 1731920000;
  const rotated = `t=${now},v1=${"0".repeat(64)},v1=${signature(body, now)}`;
  assert.doesNotThrow(() => verifyWebhook(body, rotated, ["old", SECRET], now));
  assert.throws(() => verifyWebhook(Buffer.concat([body, Buffer.from(" ")]), rotated, [SECRET], now), SignatureError);
  assert.throws(() => verifyWebhook(body, rotated, [], now), SignatureError);
  for (const offset of [-300, 300]) {
    const t = now + offset;
    assert.doesNotThrow(() => verifyWebhook(body, header(body, t), [SECRET], now));
  }
  for (const offset of [-301, 301]) {
    const t = now + offset;
    assert.throws(() => verifyWebhook(body, header(body, t), [SECRET], now), SignatureError);
  }
  for (const h of [undefined, "", `t=${now},v1=abcd`, `t=${now},t=${now},v1=${signature(body, now)}`]) {
    assert.throws(() => verifyWebhook(body, h, [SECRET], now), SignatureError);
  }
  const invalidUtf8 = Buffer.from([0xff, 0x80, 0x00]);
  assert.doesNotThrow(() => verifyWebhook(invalidUtf8, header(invalidUtf8, now), [SECRET], now));
