    assert.equal(store.listRefunds().length, 0);
  });
});

test("normal deliveries and replays deduplicate without rewriting raw events, state, or audit", async () => {
  await withApp(async (url, store, dir) => {
    const now = Math.floor(Date.now() / 1000);
    const body = JSON.stringify(event("evt_persist"), null, 2) + "\n";
    const response = await fetch(url, { method: "POST", body, headers: { "paygate-signature": header(body, now) } });
    assert.equal(response.status, 200);
    assert.deepEqual(await response.json(), { received: true, duplicate: false });
    assert.equal(store.listRefunds()[0].status, "auto_approved");
    const before = snapshot(dir);
    const retry = await fetch(url, { method: "POST", body: body + " ", headers: { "paygate-signature": header(body + " ", now) } });
    assert.deepEqual(await retry.json(), { received: true, duplicate: true });
    // No original signature is needed when replay authentication is valid.
    const replay = await fetch(url, { method: "POST", body, headers: {
      "x-replay-timestamp": String(now), "x-replay-signature": `v1=${signature(body, now)}`,
    } });
    assert.deepEqual(await replay.json(), { received: true, duplicate: true });
    assert.deepEqual(snapshot(dir), before);
    const reopened = new Store(dir);
    assert.equal(processEvent(reopened, POLICY, parseEvent(body)).outcome, "duplicate");
    assert.deepEqual(snapshot(dir), before);
    assert.equal(reopened.listRefunds().length, 1);
  });
});

test("cancellations deduplicate their updates and audits, including ignored cancellations", () => {
  for (const amount of [500000, 500001]) {
    const dir = mkdtempSync(join(tmpdir(), "pay381-cancel-"));
    try {
      const store = new Store(dir);
      processEvent(store, POLICY, event("evt_request", "refund.requested", amount));
      const cancellation = event("evt_cancel", "refund.cancelled");
      processEvent(store, POLICY, cancellation);
      assert.equal(store.listRefunds()[0].status, amount === 500000 ? "auto_approved" : "cancelled");
      const before = snapshot(dir);
      assert.equal(processEvent(store, POLICY, cancellation).outcome, "duplicate");
      assert.deepEqual(snapshot(dir), before);
    } finally {
      rmSync(dir, { recursive: true, force: true });
    }
  }
});

test("configured policy matches Dana's inclusive INR-only threshold and signature windows stay narrow", () => {
  const policy = JSON.parse(readFileSync(new URL("../config/refunds.json", import.meta.url), "utf8"));
  assert.equal(policy.auto_approve_max_minor, 500000);
  assert.deepEqual(policy.auto_approve_currencies, ["INR"]);
  assert.equal(decideStatus(policy, 500000, "INR"), "auto_approved");
  assert.equal(decideStatus(policy, 500001, "INR"), "pending_review");
  assert.equal(decideStatus(policy, 1, "USD"), "pending_review");
  const paygate = loadPaygateConfig({});
  assert.equal(paygate.tolerance_s, 300);
  assert.equal(paygate.replay_tolerance_s, 300);
});
